//! j8bytecode: j8's virtual instruction set, an accumulator-based register bytecode (compiled from JS by j8compiler,
//! run by j8executor, turned into machine code by j8jit). The dependency root: it depends on no other j8 crate.
//!
//! Every type (instructions, operators, constants, functions, modules) is defined in `insn.json` and generated by
//! `j8macros::enums!`.
//!
//! Assembly / disassembly: `text.parse::<Module>()` / `module.to_string()`, inverses of each other.
extern crate alloc;

mod asm;
mod disasm;
mod fuse;
mod insn;

pub use asm::AsmError;
pub use fuse::Unfused;
pub use insn::{BinaryOp, CompareOp, Const, Constant, EvalName, EvalScope, Function, FunctionKind, Insn, Label, Mode, Module, PropertyKind, Reg, UnaryOp};
